    static func image(_ name: String, size: CGFloat, color: NSColor, template: Bool = false) -> NSImage? {
        guard let paths = glyphs[name] else { return nil }
        let hex = template ? "#000000" : color.hexRGB
        let body = paths.map { "<path fill-rule=\"evenodd\" fill=\"\(hex)\" d=\"\($0)\"/>" }.joined()
        let svg = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" width=\"\(Int(size))\" height=\"\(Int(size))\">\(body)</svg>"
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.size = NSSize(width: size, height: size)
        image.isTemplate = template
        return image
    }

    static func emailCheck(size: CGFloat, color: NSColor, template: Bool = false) -> NSImage? {
        image("email-check", size: size, color: color, template: template)
    }
}

extension NSColor {
    var hexRGB: String {
        let c = usingColorSpace(.sRGB) ?? self
        let r = Int((c.redComponent * 255).rounded())
        let g = Int((c.greenComponent * 255).rounded())
        let b = Int((c.blueComponent * 255).rounded())
        return String(format: "#%02X%02X%02X", r, g, b)
    }
}
